import {serviceCatalog} from './services.js';
const $=(q,root=document)=>root.querySelector(q), $$=(q,root=document)=>[...root.querySelectorAll(q)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format((v||0)/100);
const date=v=>new Date(v).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
const iconPaths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',search:'M21 21l-5-5 M19 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',arrow:'M5 12h14 m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',plus:'M12 5v14 M5 12h14',close:'m6 6 12 12 M6 18 18 6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6z m-5 10 3 3 7-7',factory:'M3 21V9l6 4V7l7 5V3h5v18z M6 17h2 m4 0h2 m3 0h2',excavator:'M3 19h15l2-3H6z M8 16V9h6v7 M14 9l2-6h3l3 10-3 2',kitchen:'M3 4h18v17H3z M3 8h18 M7 12h10v5H7z M7 6h1 m4 0h1 m4 0h1',generator:'M3 6h18v13H3z M6 10h5v5H6z m9-5h3 m-3 4h3 M6 19v2 m12-2v2',food:'M4 10h5v11H4z M5 4h3v6 M14 8h6v13h-6z M15 3h4v5',textile:'M4 5h16v15H4z M8 2v20 M12 2v20 M16 2v20 M2 9h20 M2 14h20',tractor:'M6 19a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M19 19a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M6 11V4h7l3 9H9 M16 6h4v7',truck:'M1 5h13v12H1z m13 4h5l4 5v3h-9 M6 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4 M18 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4',users:'M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2 M8.5 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M20 21v-2a4 4 0 0 0-3-3.8 M17 3.2a4 4 0 0 1 0 7.6',file:'M14 2H4v20h16V8z M14 2v6h6 M8 13h8 m-8 4h6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3l-1 3-3 1-2 4 2 2 1 4 3 1 1 3h4l1-3 3-1 2-4-2-2-1-4-3-1-1-3z',logout:'M9 3H3v18h6 M9 12h12 m-5-5 5 5-5 5',chart:'M3 3v18h18 M7 15l4-5 4 3 6-9',briefcase:'M3 7h18v14H3z M8 7V3h8v4 M3 12h18 M10 12v3h4v-3',wallet:'M3 5h17v16H3z M3 5V3h14v2 M15 11h7v6h-7z',check:'m5 12 4 4L19 6',menu:'M3 6h18 M3 12h18 M3 18h18',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',edit:'m16 3 5 5-12 12-6 1 1-6z M14 5l5 5',tool:'m14 6 4 4 4-4a6 6 0 0 1-8 8L5 23l-4-4 9-9a6 6 0 0 1 8-8z'};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.grid}"/></svg>`;}
const logo=()=>`<span class="brand-mark"><svg viewBox="0 0 60 48" aria-hidden="true"><path fill="currentColor" d="M2 38 22 7h16L18 38zM30 7h16l12 14-16 20H24l18-21z"/></svg></span><span><strong>Rebuild Bharat<span class="tm">™</span></strong><small>Industrial Asset Recovery & Business Exchange</small></span>`;
const state={compare:[],user:null,demo:false,categories:[],favourites:[],page:'',data:[],search:'',settings:{},mobile:false};
let renderToken=0,previousFocus=null;
async function api(path,body){const r=await fetch('/api'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-Rebuild-Request':'1'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await r.json();}catch{throw Error('The server returned an unreadable response');}if(!r.ok)throw Error(data.error||'Request failed');return data;}
function toast(message,error=false){const el=document.createElement('div');el.className='toast '+(error?'error':'');el.setAttribute('role',error?'alert':'status');el.textContent=message;$('#toast-root').append(el);setTimeout(()=>el.remove(),5000);}
function badge(status){let cls='neutral';if(['Published','Approved','Completed','Paid','Delivered','Accepted','Active','Verified','Won'].includes(status))cls='success';if(['Submitted','Pending','Requested','In review','Scheduled','Quoted','Screening','Negotiation','Draft'].includes(status))cls='warning';if(['Rejected','Disputed','Void','Disabled','Lost'].includes(status))cls='danger';return `<span class="badge ${cls}">${esc(status)}</span>`;}
const button=(label,action,cls='primary',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const empty=(title,description,action='')=>`<div class="empty">${icon('briefcase')}<h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;
function modal(title,body,wide=false){previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><header><div><span class="eyebrow">REBUILD BHARAT</span><h2 id="modal-title">${esc(title)}</h2></div>${button(icon('close'),'close-modal','icon-btn','aria-label="Close dialog"')}</header>${body}</section></div>`;$('.modal input,.modal button,.modal select')?.focus();document.body.classList.add('modal-open');}
function closeModal(){$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');previousFocus?.focus();}
const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${esc(label)}</span><input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;
const area=(label,name,value='',extra='')=>`<label class="field full"><span>${esc(label)}</span><textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const select=(label,name,options,value='',extra='')=>`<label class="field"><span>${esc(label)}</span><select name="${name}" ${extra}>${options.map(o=>{const v=typeof o==='string'?o:o.id,t=typeof o==='string'?o:o.name;return `<option value="${esc(v)}" ${(Array.isArray(value)?value.map(String).includes(String(v)):String(v)===String(value))?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;
const formEnd=(label='Save changes')=>`<p class="form-error" role="alert"></p><div class="form-actions">${button('Cancel','close-modal','secondary')}<button class="btn primary" type="submit">${esc(label)} ${icon('arrow')}</button></div></form>`;
function header(){return `<header class="public-header"><a class="brand" href="#/">${logo()}</a><nav aria-label="Main navigation" class="${state.mobile?'open':''}"><a href="#/" class="${state.page==='home'?'active':''}">Home</a>${state.features.trade?`<a href="#/browse">Buy Equipment ${icon('down')}</a><a href="#/portal/assets">Sell Equipment ${icon('down')}</a>`:''}${state.features.business?'<a href="#/services/business">Businesses for Sale</a>':''}${state.features.auctions?'<a href="#/auctions">Auctions</a>':''}${state.features.rentals?'<a href="#/rentals">Rentals</a>':''}${serviceCatalog.some(s=>state.features[s.key])?`<a href="#/services">Services ${icon('down')}</a>`:''}</nav><div class="header-actions">${state.features.trade?`<a class="icon-btn" href="#/browse" aria-label="Search equipment">${icon('search')}</a>`:''}${state.user?`<a class="avatar" href="#/portal/dashboard" title="Open your portal">${esc(state.user.name.slice(0,2).toUpperCase())}</a>`:`<a class="btn small secondary" href="#/login">Sign in ${icon('arrow')}</a>`}<button class="icon-btn mobile-toggle" data-action="mobile" aria-label="Toggle menu">${icon('menu')}</button></div></header>`;}
const footer=()=>`<footer class="footer"><a class="brand" href="#/">${logo()}</a><p>Giving business assets a second life.</p><div>${state.features.trade?'<a href="#/browse">Marketplace</a>':''}<a href="#/services">Our services</a>${state.features.inspection?'<a href="#/services/inspection">Inspections</a>':''}${state.features.business?'<a href="#/services/business">Sell your business</a>':''}<a href="mailto:${esc(state.settings.contactEmail||'hello@rebuildbharat.in')}">Contact us</a></div><small>© ${new Date().getFullYear()} Rebuild Bharat. Inspection scope, ownership review and due diligence are separate checks.</small></footer>`;
const demoBanner=()=>state.demo?'<div class="demo-banner"><span class="demo-dot"></span> DEMONSTRATION ENVIRONMENT <span>All listings, prices and records are illustrative.</span></div>':'';
const spritePositions={factory:'-30px -514px',cnc:'-30px -514px',excavator:'-220px -514px',kitchen:'-390px -514px',food:'-565px -514px',generator:'-740px -514px',textile:'-910px -514px',tractor:'-1095px -514px',truck:'-1260px -514px'};
function media(type='factory',cls=''){return `<div class="equipment-image ${cls}" role="img" aria-label="${esc(type)} design reference imagery" style="--sprite-position:${spritePositions[type]||spritePositions.factory}"></div>`;}
function assetCard(a){return `<article class="asset-card"><a href="#/asset/${a.id}" class="asset-photo">${assetMedia(a)}<span class="badge image-badge">${state.demo?'Demo listing':esc(a.condition)}</span></a><button class="favourite ${state.favourites.includes(a.id)?'selected':''}" data-action="favourite" data-id="${a.id}" aria-label="${state.favourites.includes(a.id)?'Unsave':'Save'} ${esc(a.title)}">${icon('heart')}</button><div class="asset-card-body"><small class="muted">${esc(a.category_name)}</small><a href="#/asset/${a.id}"><h3>${esc(a.title)}</h3></a><div class="asset-meta"><span>${icon('clock')}${esc(a.year||'Year n/a')}</span><span>${icon('pin')}${esc(a.location.split(',')[0])}</span></div><div class="asset-card-bottom"><strong>${a.price?money(a.price):'Request price'}</strong><a class="circle-arrow" aria-label="View ${esc(a.title)}" href="#/asset/${a.id}">${icon('arrow')}</a></div><button class="compare-button" data-action="compare" data-id="${a.id}" aria-pressed="${state.compare.includes(a.id)}">${icon('plus')} ${state.compare.includes(a.id)?'In comparison':'Compare'}</button></div></article>`;}
function publicHome(assets,cats){
 const roots=cats.filter(c=>!c.parent_id),trade=state.features.trade;
 const available=serviceCatalog.filter(service=>state.features[service.key]);
 return `${header()}<main class="marketplace"><section class="hero"><div class="hero-copy"><span class="eyebrow">GIVING BUSINESS ASSETS A SECOND LIFE <i></i></span><h1>${esc(state.settings.headline||'Every Asset Has a Second Opportunity.').replace('Second Opportunity.','<span>Second Opportunity.</span>')}</h1><p>${trade?esc(state.settings.subtitle):'Discover the Rebuild Bharat services currently available for your business assets.'}</p><div class="hero-actions">${trade?`<a class="btn primary" href="#/browse">${icon('briefcase')} Buy Equipment</a><a class="btn white" href="#/portal/assets">${icon('plus')} Sell Equipment</a>`:'<a class="btn primary" href="#/services">Explore available services</a>'}${state.features.business?`<a class="btn white" href="#/services/business">${icon('factory')} Sell Your Business</a>`:''}</div><div class="hero-caption">A smarter way to recover value from business assets.</div></div><div class="hero-machine" role="img" aria-label="Excavator on a construction site"></div><div class="hero-note"><span class="icon-tile">${icon('briefcase')}</span><strong>More possibilities.<br>For your business assets.</strong><p>Explore the services available from our team.</p><a href="#/services">Explore our services ${icon('arrow')}</a></div></section>
 <div class="search-services">${trade?`<form id="hero-search" class="universal-search">${icon('search')}<input name="q" placeholder="Search JCB, CNC machines, generators…" aria-label="Search equipment"><select name="category" aria-label="Category"><option value="">All Categories</option>${roots.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><button class="btn primary" type="submit">Search ${icon('arrow')}</button></form>`:''}${available.length?`<div class="service-strip">${available.filter(s=>!['trade','business','auctions','rentals'].includes(s.key)).slice(0,3).map(service=>`<a href="#/services/${service.key}">${icon(service.icon)}<span>${service.name}</span></a>`).join('')}</div>`:''}</div>
 ${trade?`<section class="section"><div class="section-heading"><div><span class="eyebrow">FIND YOUR NEXT OPPORTUNITY</span><h2>Explore by Category</h2></div><a class="btn secondary small" href="#/browse">View all categories ${icon('arrow')}</a></div>${roots.length?`<div class="category-grid">${roots.slice(0,8).map(c=>`<a class="category-card" href="#/browse?category=${c.id}">${media(c.icon)}<div><span class="icon-tile small">${icon(c.icon)}</span><strong>${esc(c.name)}</strong></div></a>`).join('')}</div>`:empty('Categories are launching soon','Please check back for available equipment.')}</section>`:''}
 ${trade||state.features.inspection?`<div class="market-lower ${!trade||!state.features.inspection?'single-column':''}">${trade?`<section class="section featured"><div class="section-heading"><div><span class="eyebrow">DISCOVER WHAT’S POSSIBLE</span><h2>Featured Equipment</h2></div><a class="text-link" href="#/browse">View all ${icon('arrow')}</a></div><div class="asset-grid">${assets.slice(0,4).map(assetCard).join('')||empty('Your next opportunity is on its way','New equipment will appear here after review and publication.')}</div></section>`:''}${state.features.inspection?`<section class="certified"><span class="eyebrow">CLARITY BEFORE COMMITMENT</span><h2>${icon('shield')} Rebuild Certified</h2><h3>Know the asset. Make a better decision.</h3><p>Documented technical findings, evidence and clear inspection limitations—so you know what was checked.</p><div class="certified-items">${[['search','Technical inspection'],['file','Condition report'],['users','Expert review']].map(([i,t])=>`<span>${icon(i)}${t}</span>`).join('')}</div><a class="btn white" href="#/services/inspection">Explore inspection services ${icon('arrow')}</a><small>Ownership, valuation and legal checks are separate.</small></section>`:''}</div>`:''}
 <section class="section"><div class="section-heading"><h2>Services for your business</h2><a href="#/services" class="text-link">View available services ${icon('arrow')}</a></div><div class="home-service-grid">${available.map(service=>`<a class="panel" href="#/${service.route||'services/'+service.key}"><span class="icon-tile">${icon(service.icon)}</span><small>${service.brand}</small><h3>${service.name}</h3><p>${service.description}</p></a>`).join('')||empty('Services are launching soon','Please check back for updates.')}</div></section>
 ${trade?`<section class="selling-banner"><span class="icon-tile">${icon('factory')}</span><div><span class="eyebrow">UNLOCK THE VALUE IN IDLE ASSETS</span><h2>Have machinery you no longer need?</h2><p>Give useful equipment a new opportunity.</p></div><a class="btn primary" href="#/portal/assets">Start selling ${icon('arrow')}</a></section>`:''}</main>${footer()}`;
}
function browse(assets,cats,params){return `${header()}<main class="marketplace"><div class="page-title"><span class="eyebrow">THE REBUILD MARKETPLACE</span><h1>Find your next working asset.</h1><p>Explore equipment. Compare possibilities. Buy with clarity.</p></div><form id="browse-search" class="browse-controls"><label class="search-input">${icon('search')}<input name="q" value="${esc(params.get('q')||'')}" placeholder="What are you looking for?" aria-label="Search"></label>${select('Category','category',[{id:'',name:'All categories'},...cats],params.get('category')||'')}${field('Location','location',params.get('location')||'','text','placeholder="City or state"')}${select('Sort by','sort',[{id:'',name:'Newest first'},{id:'price-asc',name:'Price: low to high'},{id:'price-desc',name:'Price: high to low'}],params.get('sort')||'')}<button class="btn primary">Find equipment ${icon('arrow')}</button></form>${browseExtraFilters(cats,params)}<div class="results-label"><strong>${assets.length} opportunities</strong><span>${state.demo?'Clearly labelled demonstration inventory':'Published and available listings'}</span></div><div class="browse-grid">${assets.map(assetCard).join('')||empty('No matching equipment','Try another category or a broader search.', '<a class="btn secondary" href="#/browse">Clear filters</a>')}</div></main>${footer()}`;}
function assetDetail(a){return `${header()}<main class="marketplace"><a class="back-link" href="#/browse">← Back to marketplace</a><div class="detail-grid"><section><div class="detail-image">${assetMedia(a)}</div><div class="panel"><h2>About this equipment</h2><p class="preserve">${esc(a.description)}</p><h3>Technical specifications</h3><dl class="specs">${[['Brand',a.brand],['Model',a.model],['Manufacture year',a.year],['Condition',a.condition],...Object.entries(a.specs||{})].map(([k,v])=>`<div><dt>${esc(k.replaceAll('_',' '))}</dt><dd>${esc(Array.isArray(v)?v.join(', '):v)}</dd></div>`).join('')}</dl></div></section><aside class="panel detail-summary"><span class="eyebrow">${esc(a.category_name)}</span><h1>${esc(a.title)}</h1><p>${icon('pin')} ${esc(a.location)}</p>${badge(a.condition)}<div class="detail-price">${a.price?money(a.price):'Price on request'}</div><p class="muted">Commercial terms and availability to be confirmed with the seller.</p>${state.features.trade?button('Enquire about this asset '+icon('arrow'),'enquire','primary full-width',`data-id="${a.id}"`):''}${state.features.inspection?button(icon('shield')+' Request inspection','request-inspection','secondary full-width',`data-id="${a.id}"`):''}${state.features.trade?button(icon('heart')+' Save asset','favourite','ghost full-width',`data-id="${a.id}"`):''}<div class="notice"><strong>Make an informed purchase</strong><p>Technical condition, ownership documents, valuation and legal due diligence require separate checks. An inspection is not a guarantee.</p></div></aside></div></main>${footer()}`;}
function auth(register=false){return `${header()}<main class="auth-layout"><section class="auth-story"><span class="eyebrow">WELCOME TO REBUILD BHARAT</span><h1>A second life for assets.<br><span>A new chapter for business.</span></h1><p>One account to buy, sell and manage your industrial asset opportunities.</p><div class="auth-illustration">${icon('factory')}</div><span>Built for businesses. Backed by human expertise.</span></section><section class="auth-panel"><a class="brand" href="#/">${logo()}</a><h2>${register?'Let’s build new possibilities.':'Good to see you again.'}</h2><p class="muted">${register?'Create your buyer and seller account.':'Sign in to your Rebuild Bharat workspace.'}</p><form id="${register?'register':'login'}">${register?field('Your full name','name','','text','required autocomplete="name"')+field('Company name','company','','text','required autocomplete="organization"'):''}${field('Email address','email','','email','required autocomplete="username"')}${field('Password','password','','password',`required minlength="${register?12:1}" autocomplete="${register?'new-password':'current-password'}"`)}${register?'<small class="muted">Use at least 12 characters. You can buy and sell using the same account.</small>':''}<p class="form-error" role="alert"></p><button class="btn primary full-width" type="submit">${register?'Create account':'Sign in'} ${icon('arrow')}</button></form><p>${register?'Already have an account?':'New to Rebuild Bharat?'} <a class="text-link" href="#/${register?'login':'register'}">${register?'Sign in':'Create an account'}</a></p>${state.demo?`<div class="demo-login"><strong>Explore the demo</strong><p>Sample data only. Choose a workspace to fill the sign-in form.</p><div>${[['admin','Super Admin'],['customer','Seller'],['buyer','Buyer'],['inspector','Inspector'],['operations','Operations'],['finance','Finance']].map(([id,name])=>button(name,'demo-login','secondary small',`data-role="${id}"`)).join('')}</div></div>`:''}</section></main>`;}
const navItems=[['dashboard','Overview','grid'],['assets','Assets & listings','factory'],['saved','Saved equipment','heart'],['categories','Categories & launch','grid'],['auctions','Auctions','chart'],['rentals','Rentals & bookings','clock'],['features','Service launch controls','settings'],['enquiries','Enquiries & offers','briefcase'],['certificates','Technical certificates','shield'],['inspection','Inspections','shield'],['repair','Refurbishment','tool'],['logistics','Logistics','truck'],['liquidation','Factory liquidation','factory'],['business','Businesses for sale','briefcase'],['lead','CRM & leads','users'],['transaction','Transactions','wallet'],['invoice','Finance & invoices','wallet'],['users','Users & companies','users'],['data-room','Shared data rooms','shield'],['documents','Private documents','file'],['notifications','Notifications','bell'],['cms','Website content','edit'],['audit','Audit trail','clock'],['profile','My company','settings']];
const allowPage=p=>{const r=state.user?.role;if(r==='admin')return true;if(p==='saved')return r==='customer'||r==='admin';if(['auctions','rentals'].includes(p))return r==='admin'||r==='operations'||p==='auctions'&&r==='auction'||r==='customer';if(['dashboard','profile','notifications','documents','data-room','certificates'].includes(p))return true;if(r==='customer')return ['assets','enquiries','inspection','repair','logistics','liquidation','business','transaction','invoice'].includes(p);if(r==='operations')return ['assets','enquiries','inspection','repair','logistics','liquidation','business','lead','transaction'].includes(p);if(r==='finance')return p==='invoice';if(r==='inspector')return p==='inspection';if(r==='refurbisher')return p==='repair';if(r==='logistics')return p==='logistics';return false;};
const roleName=r=>({admin:'Super Admin',customer:'Customer',operations:'Sales & Operations',inspector:'Inspection Partner',refurbisher:'Refurbishment Partner',logistics:'Logistics Partner',finance:'Finance & Accounts',auction:'Auction Manager'}[r]||r);
function portalShell(page,content){return `<div class="workspace"><aside class="sidebar ${state.mobile?'open':''}"><a href="#/" class="brand">${logo()}</a><span class="sidebar-caption">YOUR WORKSPACE</span><nav aria-label="Workspace navigation">${navItems.filter(([id])=>allowPage(id)).map(([id,name,i])=>`<a href="#/portal/${id}" class="${page===id?'active':''}">${icon(i)}<span>${name}</span>${page===id?'<span class="nav-dot"></span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="#/">${icon('arrow')} Visit marketplace</a><button data-action="logout">${icon('logout')} Sign out</button><div class="sidebar-user"><span class="avatar">${esc(state.user.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(state.user.name)}</strong><small>${roleName(state.user.role)}</small></div></div></div></aside><div class="workspace-main"><header class="workspace-header"><button class="icon-btn mobile-toggle" data-action="mobile" aria-label="Toggle workspace menu">${icon('menu')}</button><div class="breadcrumb">Workspace ${icon('chevron')} <strong>${esc(navItems.find(x=>x[0]===page)?.[1]||page)}</strong></div><div class="header-actions"><span class="workspace-date">${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}</span><a href="#/portal/notifications" class="icon-btn" aria-label="Notifications">${icon('bell')}</a><a href="#/portal/profile" class="avatar">${esc(state.user.name.slice(0,2).toUpperCase())}</a></div></header><main class="portal-content">${content}</main><div class="workspace-foot">Rebuild Bharat workspace <span>Connected · Data stored locally</span></div></div></div>`;}
const pageTitle=(eyebrow,title,desc,action='')=>`<div class="portal-title"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
function dashboard(d){const labels=state.user.role==='customer'?['Company assets','Live listings','Open enquiries','Service workflows']:['Total assets','Live listings','Enquiries','Awaiting moderation'];const values=[d.assets,d.published,d.enquiries,state.user.role==='customer'?d.workflows:d.pending];return pageTitle('YOUR BUSINESS, IN FOCUS',`Welcome back, ${esc(state.user.name.split(' ')[0])}.`,'A clear view of your assets, opportunities and next steps.',`<a class="btn primary" href="#/portal/assets">${icon('plus')} Manage assets</a>`)+`<div class="stats-grid">${labels.map((label,i)=>`<section class="stat-card"><div><span>${label}</span><span class="stat-icon">${icon(['factory','briefcase','users','clock'][i])}</span></div><strong>${values[i]}</strong><small>${['Across your workspace','Visible in enabled categories','Buyer and seller conversations','Keep things moving'][i]}</small></section>`).join('')}</div><div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-title"><h2>Marketplace at a glance</h2><span class="badge">Current totals</span></div><div class="bar-chart">${[['Assets',d.assets],['Published',d.published],['Enquiries',d.enquiries],['Workflows',d.workflows]].map(([label,n])=>`<div class="bar-column"><span>${n}</span><div class="bar" style="height:${Math.max(4,n/Math.max(d.assets,d.published,d.enquiries,d.workflows,1)*150)}px"></div><small>${label}</small></div>`).join('')}</div></section><section class="panel dark-panel"><span class="eyebrow">A MARKETPLACE ON YOUR TERMS</span><h2>${d.categories} categories<br>currently available.</h2><p>Control what launches and when. Your category data stays safely preserved.</p><a href="#/portal/${state.user.role==='admin'?'categories':'assets'}" class="btn primary">${state.user.role==='admin'?'Manage launch controls':'View your listings'} ${icon('arrow')}</a></section><section class="panel"><div class="panel-title"><h2>Recent updates</h2><a href="#/portal/notifications" class="text-link">View all ${icon('arrow')}</a></div>${d.activity.length?d.activity.map(n=>`<div class="activity"><span class="icon-tile small">${icon('bell')}</span><div><p>${esc(n.message)}</p><small>${date(n.created_at)}</small></div></div>`).join(''):empty('You’re all caught up','Your account and workflow updates will appear here.')}</section><section class="panel"><h2>Keep your business moving</h2><div class="quick-links">${[['assets','Manage equipment','Create and track your listings','factory'],['enquiries','Continue a conversation','Review enquiries and offers','users'],['inspection','Inspection support','Track requests and reports','shield']].filter(([p])=>allowPage(p)).map(([p,t,d,i])=>`<a href="#/portal/${p}"><span class="icon-tile">${icon(i)}</span><div><strong>${t}</strong><small>${d}</small></div>${icon('arrow')}</a>`).join('')}</div></section></div>`;}
function assetsPage(rows){const admin=['admin','operations'].includes(state.user.role);return pageTitle('ASSET REGISTRY & MARKETPLACE','Assets & listings','Physical assets and marketplace listings are tracked separately.',state.user.role!=='operations'&&(state.user.role==='admin'||state.features.trade)?button(icon('plus')+' Add equipment','asset-form'):'' )+`<div class="table-toolbar"><label class="search-input">${icon('search')}<input data-filter="table" placeholder="Search your assets…" aria-label="Filter assets"></label><span>${rows.length} assets</span></div><div class="panel table-wrap"><table><thead><tr><th>Equipment</th><th>Category</th><th>Asking price</th><th>Review / listing</th><th>Actions</th></tr></thead><tbody>${rows.map(a=>`<tr><td><div class="table-asset">${media(a.icon)}<div><strong>${esc(a.title)}</strong><small>${esc(a.location)} · ${esc(a.id.slice(0,8))}</small></div></div></td><td>${esc(a.category_name)}</td><td class="nowrap">${money(a.price)}</td><td>${badge(a.review_status)}</td><td><div class="row-actions">${['Draft','Rejected','Withdrawn'].includes(a.review_status)&&state.user.role!=='operations'?button(icon('edit'),'asset-form','icon-btn',`data-id="${a.id}" aria-label="Edit ${esc(a.title)}"`):''}${(state.features.trade||admin)&&(a.review_status==='Draft'||['Rejected','Withdrawn'].includes(a.review_status))?button('Submit','asset-status','secondary small',`data-id="${a.id}" data-status="Submitted"`):''}${admin&&a.review_status==='Submitted'?button('Approve','asset-status','primary small',`data-id="${a.id}" data-status="Approved"`)+button('Reject','asset-status','secondary small',`data-id="${a.id}" data-status="Rejected"`):''}${admin&&a.review_status==='Approved'?button('Publish','asset-status','primary small',`data-id="${a.id}" data-status="Published"`):''}${admin&&['Published','Under offer'].includes(a.review_status)?button('Mark sold','asset-status','secondary small',`data-id="${a.id}" data-status="Sold"`):''}${!['Draft','Withdrawn','Sold','Archived','Rejected'].includes(a.review_status)?button('Withdraw','asset-status','ghost small',`data-id="${a.id}" data-status="Withdrawn"`):''}${['Draft','Rejected','Withdrawn'].includes(a.review_status)&&state.user.role!=='operations'?button('Photos','asset-photo-form','secondary small',`data-id="${a.id}"`):''}${a.listing_status==='Published'?`<a href="#/asset/${a.id}" class="icon-btn" aria-label="View asset">${icon('arrow')}</a>`:''}</div></td></tr>`).join('')}</tbody></table>${!rows.length?empty('No assets yet','Start with one piece of equipment. Save a draft before submitting it for review.',state.features.trade||state.user.role==='admin'?button('Add your first asset','asset-form'):'' ):''}</div>`;}
function categoriesPage(rows){return pageTitle('YOUR CATEGORIES. YOUR LAUNCH.','Category launch controls','Enable any category whenever you’re ready. Disabling a parent hides its subcategories.',button(icon('plus')+' Create category','category-form'))+`<div class="notice launch-notice">${icon('shield')} <div><strong>Switch off visibility, preserve the history.</strong><p>Disabled categories disappear from public browsing, results and new-listing forms. Existing assets and audit history stay intact.</p></div></div><div class="category-admin-grid">${rows.filter(c=>!c.parent_id).map(c=>`<section class="panel category-admin-card"><div class="category-admin-head"><span class="icon-tile">${icon(c.icon)}</span><button class="switch ${c.active&&!c.archived?'on':''}" role="switch" aria-checked="${!!c.active&&!c.archived}" aria-label="Enable ${esc(c.name)}" data-action="category-toggle" data-id="${c.id}"><span></span></button></div><h2>${esc(c.name)}</h2><div class="category-admin-meta">${badge(c.archived?'Archived':c.effective_active?'Active':'Disabled')}<span>${c.attributes.length} specifications · v${c.version}</span></div><div class="subcategory-list">${categoryChildren(rows,c.id)||'<p class="muted">No subcategories yet.</p>'}</div><div class="category-admin-footer">${button('Configure '+icon('edit'),'category-form','secondary small',`data-id="${c.id}"`)}${button('Add subcategory '+icon('plus'),'category-form','ghost small',`data-parent="${c.id}"`)}</div></section>`).join('')}</div>`;}
function enquiriesPage(rows){return pageTitle('TURN INTEREST INTO OPPORTUNITY','Enquiries & offers','Keep conversations, commercial terms and offer history together.')+`<div class="enquiry-list">${rows.map(e=>`<section class="panel enquiry-card"><div class="panel-title"><div><small>${esc(e.buyer_name)} · ${date(e.created_at)}</small><h2>${esc(e.asset_title)}</h2></div>${badge(e.status)}</div><p class="preserve">${esc(e.message)}</p><div class="offer-history">${e.offers.map(o=>`<div class="offer"><div><strong>${money(o.amount)}</strong> ${badge(o.status)}<small>${esc(o.actor_name)} · ${date(o.created_at)}</small><p>${esc(o.terms)}</p></div>${o.actor_id!==state.user.id&&o.status==='Pending'?`<div class="row-actions">${button('Accept','offer-status','primary small',`data-id="${o.id}" data-status="Accepted"`)}${button('Decline','offer-status','secondary small',`data-id="${o.id}" data-status="Rejected"`)}</div>`:''}</div>`).join('')}</div><div class="row-actions">${e.status!=='Closed'?button(icon('plus')+' Make / counter offer','offer-form','primary small',`data-id="${e.id}"`):''}${e.status!=='Closed'?button('Close enquiry','enquiry-close','secondary small',`data-id="${e.id}"`):badge('Closed')}</div></section>`).join('')||empty('No conversations yet','Browse the marketplace and enquire about an asset to get started.','<a href="#/browse" class="btn primary">Explore equipment</a>')}</div>`;}
const kindNames={liquidation:'Factory & asset liquidation',inspection:'Inspections',repair:'Refurbishment',logistics:'Logistics',business:'Businesses for sale',lead:'CRM & leads',transaction:'Transactions',invoice:'Finance & invoices'};
const statuses={liquidation:['Submitted','Screening','Inventory review','Marketing','Negotiation','Completed','Withdrawn'],inspection:['Requested','Scheduled','In progress','Submitted','Approved','Rejected'],repair:['Requested','Quoted','Approved','In progress','QA review','Completed','Cancelled'],logistics:['Requested','Quoted','Assigned','Picked up','Delivered','Cancelled'],business:['Submitted','Screening','Qualified','Negotiation','Completed','Withdrawn'],lead:['New','Contacted','Qualified','Negotiation','Won','Lost'],transaction:['Pending','Agreement','Payment recorded','Handover','Completed','Disputed','Cancelled'],invoice:['Draft','Issued','Paid','Void']};
function recordsPage(kind,rows){const manager=['admin','operations','finance'].includes(state.user.role),create=manager||['inspection','repair','logistics','business','liquidation'].includes(kind)&&state.features[kind]&&state.user.role==='customer';return pageTitle('CONNECTED SERVICE OPERATIONS',kindNames[kind],kind==='invoice'?'Manual invoice and payment evidence tracking. No customer funds are collected.':kind==='business'?'Private business mandates, qualification and deal coordination.':'Requests, assignments and progress in one shared workspace.',create?button(icon('plus')+' New '+({liquidation:'liquidation project',inspection:'inspection',repair:'repair job',logistics:'transport request',business:'mandate',lead:'lead',transaction:'transaction',invoice:'invoice'}[kind]),'record-form','primary',`data-kind="${kind}"`):'')+`${serviceCatalog.some(s=>s.kind===kind)&&!state.features[kind]?'<div class="notice">This service is not accepting new customer requests. Existing records remain available for follow-up.</div>':''}<div class="workflow-counts">${statuses[kind].slice(0,5).map(st=>`<div><span>${st}</span><strong>${rows.filter(r=>r.status===st).length}</strong></div>`).join('')}</div><div class="panel table-wrap"><table><thead><tr><th>Reference / title</th><th>Owner / company</th><th>Assigned to</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.title)}</strong><small>${esc(r.id.slice(0,8))}${r.data.amount!==undefined?' · '+money(r.data.amount):''}</small></td><td>${esc(r.owner_name)}</td><td>${esc(r.assignee_name||'Unassigned')}</td><td>${badge(r.status)}</td><td>${date(r.updated_at)}</td><td>${button(manager||state.user.role!=='customer'?'Open / update':'View details','record-form','secondary small',`data-kind="${kind}" data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table>${!rows.length?empty('Nothing here yet','New requests and assignments will appear here.') :''}</div>${kind==='inspection'?'<div class="notice"><strong>Keep inspection scope clear.</strong><p>Record findings, limitations and uninspected items. Technical approval does not establish ownership, legal clearance or valuation.</p></div>':''}`;}
function usersPage(rows){return pageTitle('IDENTITY & ACCESS','Users & companies','Assign permission bundles, verify companies and manage access.')+`<div class="panel table-wrap"><table><thead><tr><th>User</th><th>Company</th><th>Role</th><th>Access</th><th>Actions</th></tr></thead><tbody>${rows.map(u=>`<tr><td><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></td><td>${esc(u.company_name)}<small>${u.verified?'Verified':'Verification pending'}</small></td><td>${roleName(u.role)}</td><td>${badge(u.active?'Active':'Disabled')}</td><td><div class="row-actions">${button('Manage access','user-form','secondary small',`data-id="${u.id}"`)}${button(u.verified?'Unverify company':'Verify company','verify-company','ghost small',`data-id="${u.company_id}" data-value="${u.verified?0:1}"`)}</div></td></tr>`).join('')}</tbody></table></div>`;}
function docsPage(rows){return pageTitle('PRIVATE BY DEFAULT','Company documents','Files are restricted to your company and every download is audited.',button(icon('plus')+' Upload document','document-form'))+`<div class="notice"><strong>Private document vault</strong><p>PDF, PNG and JPEG, up to 8 MB. Files download as attachments. Upload malware scanning and a managed private object store are required before production.</p></div><div class="document-grid">${rows.map(d=>`<div class="panel document-card"><span class="icon-tile">${icon('file')}</span><h3>${esc(d.name)}</h3><p>${date(d.created_at)}</p><a class="btn secondary small" href="/api/documents/${d.id}">Download ${icon('arrow')}</a></div>`).join('')||empty('No private documents','Upload company documents to your private workspace.')}</div>`;}
function notificationsPage(rows){return pageTitle('STAY IN THE LOOP','Notifications','In-app updates from your assets and service workflows.',button('Mark all as read','read-notifications','secondary'))+`<section class="panel">${rows.map(n=>`<div class="notification ${n.read?'read':''}"><span class="icon-tile">${icon('bell')}</span><div><p>${esc(n.message)}</p><small>${date(n.created_at)}</small></div>${n.read?'':'<span class="unread-dot"></span>'}</div>`).join('')||empty('All quiet for now','Updates will appear as your business moves forward.')}</section>`;}
function auditPage(rows){return pageTitle('ACCOUNTABILITY BUILT IN','Audit trail','Append-only records of privileged actions and important workflow changes.')+`<div class="panel table-wrap"><table><thead><tr><th>When</th><th>Actor</th><th>Action</th><th>Entity</th><th>Details</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="nowrap">${date(r.created_at)}<small>${new Date(r.created_at).toLocaleTimeString('en-IN')}</small></td><td>${esc(r.actor_name||'System')}</td><td><code>${esc(r.action)}</code></td><td>${esc(r.entity_type)}<small>${esc(r.entity_id.slice(0,10))}</small></td><td><code>${esc(r.details)}</code></td></tr>`).join('')}</tbody></table></div>`;}
function cmsPage(data){return pageTitle('MAKE IT YOURS','Website content','Update the public homepage copy without a deployment.')+`<section class="panel settings-panel"><h2>Homepage</h2><form id="cms">${field('Hero headline','headline',data.headline,'text','required maxlength="150"')}${area('Hero description','subtitle',data.subtitle,'required maxlength="500"')}${field('Contact email','contactEmail',data.contactEmail,'email','required')}<p class="form-error" role="alert"></p><button class="btn primary">Save website content ${icon('check')}</button></form></section>`;}
function profilePage(companies){return pageTitle('YOUR SHARED BUSINESS IDENTITY','My company','One account can buy, sell and belong to multiple companies.',button(icon('plus')+' Add company','company-form'))+`<div class="panel"><h2>${esc(state.user.name)}</h2><p>${esc(state.user.email)}</p>${badge(roleName(state.user.role))}<div class="profile-actions">${button('Change password','password-form','secondary small')}</div></div><div class="company-grid">${companies.map(c=>`<section class="panel"><span class="icon-tile">${icon('factory')}</span><h2>${esc(c.name)}</h2>${badge(c.verified?'Verified':'Verification pending')}<p class="muted">Membership grants access to this company’s assets and private documents.</p>${button('Add registered member','member-form','secondary small',`data-id="${c.id}"`)}</section>`).join('')}</div>`;}
function serviceDirectory(){return `${header()}<main class="marketplace"><div class="page-title"><span class="eyebrow">ONE PARTNER. MORE POSSIBILITIES.</span><h1>Services for every asset journey.</h1><p>Discover the Rebuild Bharat services currently available.</p></div><div class="category-admin-grid">${serviceCatalog.filter(s=>state.features[s.key]).map(s=>`<section class="panel"><span class="icon-tile">${icon(s.icon)}</span><span class="eyebrow">${s.brand}</span><h2>${s.name}</h2><p>${s.description}</p><a href="#/${s.route||'services/'+s.key}" class="btn secondary small">Explore service ${icon('arrow')}</a></section>`).join('')||empty('Services are launching soon','Please check back for our available services.')}</div></main>${footer()}`;}
function serviceUnavailable(){return `${header()}<main class="marketplace">${empty('This service is not currently available','Please explore the services currently open for requests.','<a href="#/services" class="btn primary">View available services</a>')}</main>${footer()}`;}
function servicePage(kind){const service=serviceCatalog.find(s=>s.key===kind);if(!service||!state.features[kind])return serviceUnavailable();if(service.route)return serviceDirectory();return `${header()}<main class="marketplace"><section class="service-hero"><span class="eyebrow">${service.brand}</span><h1>${service.name}</h1><p>${service.description}</p>${button('Request '+service.name.toLowerCase(),'service-request','primary',`data-kind="${service.kind}"`)}<div class="service-feature-grid">${[['users','Personal coordination','Work with our team to qualify your requirements and arrange next steps.'],['file','Clear documentation','Record requirements, progress and supporting information in your workspace.'],['shield','Controlled access','Your company information remains restricted to authorised users.']].map(([i,t,p])=>`<section class="panel"><span class="icon-tile">${icon(i)}</span><h2>${t}</h2><p>${p}</p></section>`).join('')}</div><div class="notice">${kind==='inspection'?'Technical inspection is not a defect-free guarantee. Ownership review, valuation and legal due diligence are separate checks.':'Service scope, commercial terms and responsibilities must be agreed with the team before work begins.'}</div></section></main>${footer()}`;}

async function render(){const token=++renderToken;state.mobile=false;const hash=location.hash.slice(1)||'/',[route,query='']=hash.split('?'),params=new URLSearchParams(query);let content,portal=false;$('#app').setAttribute('aria-busy','true');try{
 const me=await api('/me');state.user=me.user;state.demo=me.demo;state.settings=await api('/settings');state.features=await api('/features');if(state.user)state.favourites=await api('/favourites');
 if(route.startsWith('/portal')){if(!state.user){location.hash='/login';return;}portal=true;const page=route.split('/')[2]||'dashboard';state.page=page;if(!allowPage(page))throw Error('This workspace is not available for your role');let data;
 if(page==='dashboard')content=dashboard(await api('/dashboard'));
 else if(page==='assets'){data=await api('/assets?scope='+(['admin','operations'].includes(state.user.role)?'admin':'mine'));content=assetsPage(data);}
 else if(page==='saved'){const rows=await api('/assets');content=pageTitle('YOUR SHORTLIST','Saved equipment','Keep the opportunities you’re interested in close at hand.')+'<div class="browse-grid">'+(rows.filter(a=>state.favourites.includes(a.id)).map(assetCard).join('')||empty('Your shortlist is empty','Save assets while browsing to find them here.','<a href="#/browse" class="btn primary">Browse equipment</a>'))+'</div>';}
 else if(page==='categories'){data=await api('/categories?admin=1');state.categories=data;content=categoriesPage(data);}
 else if(page==='certificates'){data=await api('/certificates');content=certificatesPage(data);}
 else if(page==='features')content=featuresPage();
 else if(page==='auctions'){try{data=await api('/auctions');content=auctionsPage(data,true);}catch(e){content=empty('Auctions have not launched',e.message);}}
 else if(page==='rentals'){try{data=await api('/rentals');const bookings=await api('/bookings');state.bookings=bookings;content=rentalsPage(data,bookings,true);}catch(e){content=empty('Rentals have not launched',e.message);}}
 else if(page==='enquiries'){data=await api('/enquiries');content=enquiriesPage(data);}
 else if(statuses[page]){data=await api('/records?kind='+page);content=recordsPage(page,data);}
 else if(page==='users'){data=await api('/users');content=usersPage(data);}
 else if(page==='data-room'){data=await api('/data-room');content=dataRoomPage(data);}
 else if(page==='documents')content=docsPage(await api('/documents'));
 else if(page==='notifications')content=notificationsPage(await api('/notifications'));
 else if(page==='audit')content=auditPage(await api('/audit'));
 else if(page==='cms')content=cmsPage(state.settings);
 else if(page==='profile')content=profilePage(me.companies);
 state.data=data||[];content=portalShell(page,content||empty('Workspace unavailable','Return to the overview.'));
 }else{state.categories=await api('/categories');if(route==='/'){state.page='home';content=publicHome(await api('/assets'),state.categories);}else if(route==='/browse'&&!state.features.trade)content=serviceUnavailable();else if(route==='/browse'){state.page='browse';content=browse(await api('/assets?'+params),state.categories,params);}else if(route.startsWith('/asset/')){state.page='detail';const a=await api('/assets/'+route.split('/')[2]);state.currentAsset=a;content=assetDetail(a);}else if(route==='/auctions'){const rows=await api('/auctions');state.data=rows;content=header()+'<main class="marketplace">'+auctionsPage(rows,false)+'</main>'+footer();}else if(route==='/rentals'){const rows=await api('/rentals');state.data=rows;content=header()+'<main class="marketplace">'+rentalsPage(rows,[],false)+'</main>'+footer();}else if(route.startsWith('/certificate/')){const cert=await api('/certificates/'+route.split('/')[2]);content=header()+certificatePublic(cert)+footer();}else if(route==='/login'||route==='/register'){state.page='auth';content=auth(route==='/register');}else if(route==='/services')content=serviceDirectory();else if(route.startsWith('/services/'))content=servicePage(route.split('/')[2]);else content=header()+empty('Page not found','Return to the marketplace.','<a href="#/" class="btn primary">Go home</a>')+footer();}
 if(token!==renderToken)return;document.body.classList.toggle('portal-theme',portal);$('#app').innerHTML=demoBanner()+content;$('#app').removeAttribute('aria-busy');document.title=(portal?(navItems.find(x=>x[0]===state.page)?.[1]||'Workspace'):'Industrial Asset Marketplace')+' · Rebuild Bharat';
 }catch(e){if(token!==renderToken)return;$('#app').innerHTML=header()+`<main class="marketplace">${empty('We couldn’t load this page',e.message,button('Try again','retry','primary')+' <a class="btn secondary" href="#/">Home</a>')}</main>`;$('#app').removeAttribute('aria-busy');}}
async function assetForm(a={}){if(!a.id&&state.user.role!=='admin'&&!state.features.trade)throw Error('Equipment trade is not accepting new submissions');const cats=await api('/categories'),me=await api('/me');state.formDocuments=await api('/documents');if(!cats.length){toast('No categories are launched. Super Admin must enable one first.',true);return;}state.formCategories=cats;const cid=a.category_id||cats[0].id;modal(a.id?'Edit equipment':'Add equipment',`<form id="asset-form" data-id="${a.id||''}"><div class="form-grid">${field('Equipment title','title',a.title||'','text','required minlength="3" maxlength="150"')}${select('Company','company_id',me.companies,a.company_id||state.user.company_id)}${select('Category','category_id',cats,cid,'id="asset-category"')}${field('Location','location',a.location||'','text','required placeholder="City, State"')}${field('Brand','brand',a.brand||'','text','list="brand-options"')}${field('Model','model',a.model||'','text','list="model-options"')}${field('Year of manufacture','year',a.year||'','number','min="1900" max="'+(new Date().getFullYear()+1)+'"')}${select('Condition','condition',['Used','Refurbished','Unused surplus','For parts'],a.condition||'Used')}${field('Asking price (₹)','price',a.price?a.price/100:'','number','min="0" step="0.01" placeholder="0 = request price"')}${area('Description','description',a.description||'','required minlength="10" maxlength="10000"')}</div><h3>Category-specific specifications</h3><div id="dynamic-specs" class="form-grid"></div><p class="muted">This creates a draft. Submit it for moderation when you’re ready.</p>${formEnd(a.id?'Save draft':'Create draft')}`,true);renderSpecs(cid,a.specs||{});}
function renderSpecs(cid,values={}){const category=state.formCategories.find(c=>c.id===cid);$('#dynamic-specs').innerHTML=(category?.attributes||[]).map(a=>{const name='spec_'+a.key,label=a.label+(a.unit?' ('+a.unit+')':'')+(a.required?' *':''),required=a.required?'required':'';if(a.type==='boolean')return select(label,name,[{id:'',name:'Not specified'},{id:'true',name:'Yes'},{id:'false',name:'No'}],String(values[a.key]??''),required);if(a.type==='dropdown')return select(label,name,[{id:'',name:'Select…'},...(a.options||[])],values[a.key]||'',required);if(a.type==='multi-select')return select(label,name,a.options||[],values[a.key]||[],'multiple '+required);if(a.type==='file')return select(label,name,[{id:'',name:'Select a private company document'},...state.formDocuments],values[a.key]||'',required);return field(label,name,values[a.key]??'',a.type==='date'?'date':['number','measurement'].includes(a.type)?'number':'text',`${required} ${a.type==='number'||a.type==='measurement'?'step="any"':''} ${a.min!==undefined?'min="'+Number(a.min)+'"':''} ${a.max!==undefined?'max="'+Number(a.max)+'"':''} ${a.type==='file'?'placeholder="Private document reference ID"':''}`);}).join('')||'<p class="muted">No additional specifications configured.</p>';$('#brand-options')?.remove();const dl=document.createElement('datalist');dl.id='brand-options';dl.innerHTML=(category?.brands||[]).map(b=>`<option value="${esc(b)}"></option>`).join('');$('.modal form').append(dl);$('#model-options')?.remove();const models=document.createElement('datalist');models.id='model-options';models.innerHTML=(category?.models||[]).map(m=>`<option value="${esc(m.name)}">${esc(m.brand)}</option>`).join('');$('.modal form').append(models);}
function categoryForm(c={},parent=''){const options=[{id:'',name:'Top-level category'},...state.categories.filter(x=>x.id!==c.id)];modal(c.id?'Configure category':'Create category',`<form id="category-form" data-id="${c.id||''}"><div class="form-grid">${field('Category name','name',c.name||'','text','required minlength="2"')}${field('URL slug','slug',c.slug||'','text','placeholder="Automatically generated if empty"')}${select('Parent category','parent_id',options,c.parent_id||parent)}${select('Category icon','icon',['factory','excavator','kitchen','food','generator','textile','tractor','truck'],c.icon||'factory')}${field('Display order','position',c.position||0,'number','step="1"')}${select('Launch status','active',[{id:'0',name:'Off — hidden from marketplace'},{id:'1',name:'On — available to launch'}],String(c.active||0))}${field('Brands (comma separated)','brands',(c.brands||[]).join(', '))}${select('Archive','archived',[{id:'0',name:'Keep category'},{id:'1',name:'Archive and preserve history'}],String(c.archived||0))}${area('Models (one Brand:Model per line)','models',(c.models||[]).map(m=>m.brand+':'+m.name).join('\n'))}</div><div class="panel-title"><h3>Technical attribute definitions</h3>${button(icon('plus')+' Add attribute','add-attribute','secondary small')}</div><div id="attribute-builder">${(c.attributes||[]).map(attributeRow).join('')}</div><p class="muted">Configure required fields, units and allowed options. Definitions are versioned; historical asset values remain saved.</p>${formEnd(c.id?'Save category':'Create category')}`,true);}
function attributeRow(a={}){return `<div class="attribute-row"><div class="form-grid">${field('Label','attr_label',a.label||'','text','required')}${field('Key','attr_key',a.key||'','text','required pattern="[_a-z][_a-z0-9]*" placeholder="engine_hours"')}${select('Type','attr_type',['text','number','measurement','dropdown','multi-select','boolean','date','file'],a.type||'text')}${field('Unit','attr_unit',a.unit||'')}${field('Options (comma separated)','attr_options',(a.options||[]).join(', '))}${field('Minimum','attr_min',a.min??'','number','step="any"')}${field('Maximum','attr_max',a.max??'','number','step="any"')}<label class="check-field"><input name="attr_required" type="checkbox" ${a.required?'checked':''}> Required</label></div>${button(icon('close')+' Remove','remove-attribute','ghost small')}</div>`;}
async function recordForm(kind,r={},assetId=''){if(!r.id&&state.user.role==='customer'&&!state.features[kind])throw Error('This service is not accepting new requests');const manager=['admin','operations','finance'].includes(state.user.role),partner=state.user.role!=='customer',readonly=!!r.id&&!manager&&!partner;let users=[];if(manager&&['inspection','repair','logistics'].includes(kind))users=await api('/users');let assets=[];try{assets=await api('/assets?scope='+(['admin','operations'].includes(state.user.role)?'admin':'mine'));}catch{/* Finance has no asset management access. */}
 const partnerRoles={inspection:'inspector',repair:'refurbisher',logistics:'logistics'};const d=r.data||{};modal((r.id?'':'New ')+kindNames[kind],`<form id="record-form" data-id="${r.id||''}" data-kind="${kind}"><fieldset ${readonly?'disabled':''}><div class="form-grid">${field('Title','title',r.title||'','text','required minlength="3"')}${select('Workflow status','status',r.id||manager?statuses[kind]:[statuses[kind][0]],r.status||statuses[kind][0])}${!r.id?select('Related asset (optional)','asset_id',[{id:'',name:'No related asset'},...assets.map(a=>({id:a.id,name:a.title})),...(assetId&&!assets.find(a=>a.id===assetId)?[{id:assetId,name:state.currentAsset?.title||'Selected asset'}]:[])],assetId):''}${manager&&partnerRoles[kind]?select('Assign partner','assigned_to',[{id:'',name:'Unassigned'},...users.filter(u=>u.role===partnerRoles[kind]||u.role==='admin')],r.assigned_to||''):''}${field('Scheduled / target date','scheduled_date',d.scheduled_date||'','date')}${['invoice','transaction','repair','logistics'].includes(kind)?field('Amount (₹)','amount',d.amount?d.amount/100:'','number','min="0" step="0.01"'):''}${kind==='transaction'?field('Commission (₹)','commission',d.commission?d.commission/100:'','number','min="0" step="0.01"'):''}${area('Notes / requirements','notes',d.notes||'','maxlength="10000"')}${kind==='inspection'?area('Technical findings','findings',d.findings||'')+area('Scope, limitations & uninspected items','limitations',d.limitations||'')+area('Recommendations','recommendations',d.recommendations||''):''}${['invoice','transaction'].includes(kind)?field('External payment / agreement reference','reference',d.reference||''):''}</div></fieldset>${kind==='inspection'?'<div class="notice">Technical inspection does not establish legal title, valuation or defect-free condition.</div>':''}${readonly?`<div class="form-actions">${button('Close','close-modal','secondary')}</div></form>`:formEnd(r.id?'Save progress':'Submit request')}`,true);}
function enquiryForm(aid){modal('Enquire about this asset',`<form id="enquiry-form" data-id="${aid}">${area('Tell the seller what you need','message','','required minlength="5" placeholder="Availability, inspection requirements, delivery location…"')}<p class="muted">Your enquiry will be shared with the seller and authorised operations staff.</p>${formEnd('Send enquiry')}`);}
function offerForm(eid){modal('Make or counter an offer',`<form id="offer-form" data-id="${eid}">${field('Your offer (₹)','amount','','number','required min="0.01" step="0.01"')}${area('Terms and conditions','terms','','required minlength="3" placeholder="Subject to inspection, validity period, delivery conditions…"')}<p class="muted">Offer acceptance records agreement in principle. It does not collect payment or transfer ownership.</p>${formEnd('Send offer')}`);}
function userForm(u){modal('Manage account access',`<form id="user-form" data-id="${u.id}"><h3>${esc(u.name)}</h3><p>${esc(u.email)}</p>${select('Permission bundle','role',Object.keys({admin:1,customer:1,inspector:1,refurbisher:1,logistics:1,operations:1,finance:1,auction:1}).map(r=>({id:r,name:roleName(r)})),u.role)}${select('Account status','active',[{id:'1',name:'Active'},{id:'0',name:'Disabled'}],String(u.active))}<div class="notice">Changing access ends this user’s active sessions. Only grant the permissions they need.</div>${formEnd('Update access')}`);}
function signedIn(){if(!state.user){toast('Please sign in to continue');location.hash='/login';return false;}return true;}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,aid=el.dataset.id;try{
 if(await certificateAction(action,el))return;
 if(await privateAction(action,el))return;
 if(await exchangeAction(action,el))return;
 if(action==='compare'){if(state.compare.includes(aid))state.compare=state.compare.filter(x=>x!==aid);else{if(state.compare.length>=3)throw Error('Compare up to three assets at a time.');state.compare.push(aid);}if(state.compare.length<2){toast('Select one more asset to compare');await render();return;}const rows=await Promise.all(state.compare.map(id=>api('/assets/'+id)));modal('Compare equipment',`<div class="comparison-grid">${rows.map(a=>`<section><h3>${esc(a.title)}</h3><strong>${money(a.price)}</strong><dl class="specs">${[['Category',a.category_name],['Location',a.location],['Condition',a.condition],['Year',a.year],['Brand',a.brand],...Object.entries(a.specs||{})].map(([k,v])=>`<div><dt>${esc(k.replaceAll('_',' '))}</dt><dd>${esc(Array.isArray(v)?v.join(', '):v)}</dd></div>`).join('')}</dl><a href="#/asset/${a.id}" class="btn secondary small">View equipment</a></section>`).join('')}</div>`,true);return;}
 if(action==='close-modal')return closeModal();
 if(action==='mobile'){state.mobile=!state.mobile;$('.public-header nav,.sidebar')?.classList.toggle('open',state.mobile);return;}
 if(action==='retry')return render();
 if(action==='logout'){await api('/auth/logout',{});state.user=null;location.hash='/';toast('Signed out');return;}
 if(action==='demo-login'){const form=$('#login');form.elements.email.value=el.dataset.role+'@demo.rebuild.test';form.elements.password.value='RebuildDemo!2026';return;}
 if(action==='asset-form'){if(signedIn())await assetForm(state.data.find(a=>a.id===aid)||{});return;}
 if(action==='category-form')return categoryForm(state.categories.find(c=>c.id===aid)||{},el.dataset.parent);
 if(action==='add-attribute'){$('#attribute-builder').insertAdjacentHTML('beforeend',attributeRow());return;}
 if(action==='remove-attribute'){el.closest('.attribute-row').remove();return;}
 if(action==='category-toggle'){el.disabled=true;const c=state.categories.find(c=>c.id===aid);await api('/categories',{...c,active:!c.active});toast(`${c.name} ${c.active?'disabled':'enabled'}`);await render();return;}
 if(action==='asset-status'){const status=el.dataset.status;if(['Rejected','Withdrawn'].includes(status)){modal(status==='Rejected'?'Reject submission':'Withdraw listing',`<form id="status-form" data-id="${aid}" data-status="${status}">${area('Reason','reason','','required minlength="3"')}${formEnd('Confirm '+status.toLowerCase())}`);return;}await api('/assets/'+aid+'/status',{status});toast('Asset moved to '+status);await render();return;}
 if(action==='favourite'){if(!signedIn())return;await api('/favourites',{asset_id:aid});state.favourites=await api('/favourites');toast(state.favourites.includes(aid)?'Asset saved':'Asset removed from saved');await render();return;}
 if(action==='enquire'){if(signedIn())enquiryForm(aid);return;}
 if(action==='offer-form')return offerForm(aid);
 if(action==='offer-status'){await api('/offers/'+aid,{status:el.dataset.status});toast('Offer '+el.dataset.status.toLowerCase());await render();return;}
 if(action==='enquiry-close'){await api('/enquiries/'+aid,{status:'Closed'});await render();return;}
 if(action==='request-inspection'){if(signedIn())await recordForm('inspection',{},aid);return;}
 if(action==='service-request'){if(signedIn())await recordForm(el.dataset.kind);return;}
 if(action==='record-form')return await recordForm(el.dataset.kind,state.data.find(r=>r.id===aid)||{});
 if(action==='user-form')return userForm(state.data.find(u=>u.id===aid));
 if(action==='verify-company'){await api('/companies/verify',{id:aid,verified:el.dataset.value==='1'});toast('Company verification updated');await render();return;}
 if(action==='read-notifications'){await api('/notifications',{});await render();return;}
 if(action==='document-form'){const me=await api('/me');modal('Upload private document',`<form id="document-form">${select('Company','company_id',me.companies,state.user.company_id)}${field('Document','file','','file','required accept="application/pdf,image/png,image/jpeg"')}<p class="muted">PDF, PNG or JPEG · Maximum 8 MB · Only company members can download.</p>${formEnd('Upload document')}`);return;}
 if(action==='password-form'){modal('Change your password',`<form id="password-form">${field('Current password','current_password','','password','required autocomplete="current-password"')}${field('New password','new_password','','password','required minlength="12" autocomplete="new-password"')}<p class="muted">All sessions will end. Sign in again with your new password.</p>${formEnd('Change password')}`);return;}
 if(action==='company-form'){modal('Add a company',`<form id="company-form">${field('Company name','name','','text','required minlength="2"')}${formEnd('Create company')}`);return;}
 if(action==='member-form'){modal('Add a company member',`<form id="member-form" data-id="${aid}">${field('Registered user email','email','','email','required')}<div class="notice">This user will gain company-wide access, including private documents. Only the company owner can add members.</div>${formEnd('Add member')}`);return;}
 }catch(e){toast(e.message,true);el.disabled=false;}});
document.addEventListener('change',e=>{if(e.target.id==='asset-category')renderSpecs(e.target.value);});
document.addEventListener('input',e=>{if(e.target.dataset.filter==='table'){const q=e.target.value.toLowerCase();$$('tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q));}});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.id)return;event.preventDefault();const data=new FormData(form),v=Object.fromEntries(data),submit=$('button[type="submit"],button:not([type])',form),err=$('.form-error',form);if(err)err.textContent='';if(submit){submit.disabled=true;submit.dataset.old=submit.innerHTML;submit.textContent='Working…';}try{
 if(await certificateSubmit(form,v)){closeModal();await render();return;}
 if(await privateSubmit(form,v,data)){closeModal();await render();return;}
 if(await exchangeSubmit(form,v)){closeModal();await render();return;}
 if(form.id==='extra-filters'){const params=new URLSearchParams((location.hash.split('?')[1]||''));for(const [key,value] of Object.entries(v)){if(value)params.set(key,['min','max'].includes(key)?String(Math.round(Number(value)*100)):value);else params.delete(key);}location.hash='/browse?'+params;return;}
 if(form.id==='hero-search'||form.id==='browse-search'){location.hash='/browse?'+new URLSearchParams(v).toString();return;}
 if(form.id==='login'){await api('/auth/login',v);toast('Welcome back');location.hash='/portal/dashboard';return;}
 if(form.id==='register'){await api('/auth/register',v);toast('Account created. Sign in to continue.');location.hash='/login';return;}
 if(form.id==='asset-form'){const category=state.formCategories.find(c=>c.id===v.category_id),specs={};for(const a of category.attributes){const value=v['spec_'+a.key];if(value===undefined||value==='')continue;specs[a.key]=['number','measurement'].includes(a.type)?Number(value):a.type==='boolean'?value==='true':a.type==='multi-select'?data.getAll('spec_'+a.key):value;}await api('/assets',{...v,id:form.dataset.id||undefined,price:Math.round(Number(v.price||0)*100),specs});toast('Asset draft saved');}
 else if(form.id==='category-form'){const attributes=$$('.attribute-row',form).map(row=>{const get=name=>$(`[name="${name}"]`,row);return {label:get('attr_label').value,key:get('attr_key').value,type:get('attr_type').value,unit:get('attr_unit').value,options:get('attr_options').value.split(',').map(x=>x.trim()).filter(Boolean),required:get('attr_required').checked,filterable:true,...(get('attr_min').value!==''?{min:Number(get('attr_min').value)}:{}),...(get('attr_max').value!==''?{max:Number(get('attr_max').value)}:{})};});await api('/categories',{...v,id:form.dataset.id||undefined,position:Number(v.position),active:v.active==='1',archived:v.archived==='1',brands:v.brands.split(',').map(x=>x.trim()).filter(Boolean),models:v.models.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>{const [brand,...name]=x.split(':');return {brand:brand.trim(),name:name.join(':').trim()};}),attributes});toast('Category settings saved');}
 else if(form.id==='status-form'){await api('/assets/'+form.dataset.id+'/status',{status:form.dataset.status,reason:v.reason});toast('Listing status updated');}
 else if(form.id==='enquiry-form'){await api('/enquiries',{asset_id:form.dataset.id,message:v.message});toast('Enquiry sent. Track it in your workspace.');}
 else if(form.id==='offer-form'){await api('/offers',{enquiry_id:form.dataset.id,amount:Math.round(Number(v.amount)*100),terms:v.terms});toast('Offer sent');}
 else if(form.id==='record-form'){const {title,status,asset_id,assigned_to,...details}=v;for(const name of ['amount','commission'])if(details[name]!==undefined)details[name]=Math.round(Number(details[name]||0)*100);await api('/records',{id:form.dataset.id||undefined,kind:form.dataset.kind,title,status,asset_id:asset_id||null,assigned_to:assigned_to||null,data:details});toast('Workflow saved');}
 else if(form.id==='user-form'){await api('/users',{id:form.dataset.id,role:v.role,active:v.active==='1'});toast('Account access updated');}
 else if(form.id==='document-form'){const file=data.get('file');if(file.size>8*1024*1024)throw Error('File exceeds 8 MB');const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});await api('/documents',{company_id:v.company_id,name:file.name,content});toast('Private document uploaded');}
 else if(form.id==='password-form'){await api('/auth/password',v);closeModal();toast('Password changed. Please sign in again.');location.hash='/login';return;}
 else if(form.id==='company-form'){await api('/companies',v);toast('Company created');}
 else if(form.id==='member-form'){await api('/companies/members',{company_id:form.dataset.id,email:v.email});toast('Company member added');}
 else if(form.id==='cms'){await api('/settings',v);toast('Homepage content updated');await render();return;}
 closeModal();await render();
 }catch(e){if(err)err.textContent=e.message;else toast(e.message,true);}finally{if(submit?.isConnected){submit.disabled=false;submit.innerHTML=submit.dataset.old;}}});
document.addEventListener('keydown',e=>{const modalEl=$('.modal');if(!modalEl)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const items=$$('button:not([disabled]),a,input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]',modalEl).filter(x=>x.offsetParent!==null);if(!items.length){e.preventDefault();modalEl.focus();return;}const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{closeModal();window.scrollTo(0,0);render();});render();
function featuresPage(){return pageTitle('LAUNCH WHEN YOU’RE READY','Service launch controls','Choose which services customers can discover and request. Existing records remain available to your team.')+`<div class="category-admin-grid">${serviceCatalog.map(service=>`<section class="panel service-control-card"><div class="category-admin-head"><span class="icon-tile">${icon(service.icon)}</span><button class="switch ${state.features[service.key]?'on':''}" role="switch" aria-checked="${!!state.features[service.key]}" aria-label="Enable ${service.name}" data-action="feature-toggle" data-key="${service.key}"><span></span></button></div><span class="eyebrow">${service.brand}</span><h2>${service.name}</h2><p class="muted">${service.description}</p>${badge(state.features[service.key]?'Active':'Disabled')}</section>`).join('')}</div><div class="notice"><strong>Your services. Your launch schedule.</strong><p>Turning a service off hides its public offering and blocks new customer requests. Your team can still access existing records and finish ongoing work. Category launch controls remain independent.</p></div>`;}
function auctionsPage(rows,portal){const manager=portal&&['admin','auction','operations'].includes(state.user.role);return pageTitle('REBUILD AUCTIONS','Industrial auctions','Request participation, follow the current bid and make a server-validated offer.',manager?button(icon('plus')+' Create auction','auction-form'):'')+`${portal&&!state.features.auctions?'<div class="notice">Auctions are hidden publicly. Super Admin can launch them from Service launch controls.</div>':''}<div class="exchange-grid">${rows.map(a=>`<section class="panel exchange-card">${media(a.icon)}<div class="panel-title"><h2>${esc(a.title)}</h2>${badge(a.phase)}</div><p class="muted">${esc(a.asset_title)} · ${esc(a.location)}</p><div class="exchange-price"><small>${a.current_bid?'Current bid':'Opening bid'}</small><strong>${money(a.current_bid||a.start_price)}</strong><span>${a.bid_count} bids · ${a.reserve_met?'Reserve met':'Reserve not met'}</span></div><dl class="specs"><div><dt>Starts</dt><dd>${new Date(a.starts_at).toLocaleString('en-IN')}</dd></div><div><dt>Ends</dt><dd>${new Date(a.ends_at).toLocaleString('en-IN')}</dd></div><div><dt>Bid increment</dt><dd>${money(a.increment)}</dd></div></dl><div class="row-actions">${manager?button('Review bidders','auction-participants','secondary small',`data-id="${a.id}"`)+(a.phase==='Ended'?button('Close & record result','auction-close','primary small',`data-id="${a.id}"`):''):!a.participant_status?button('Request bidder approval','auction-join','primary small',`data-id="${a.id}"`):a.participant_status==='Approved'&&a.phase==='Live'?button('Place bid','auction-bid-form','primary small',`data-id="${a.id}"`):badge('Bidder: '+a.participant_status)}${button(icon('clock')+' Refresh','retry','secondary small')}</div></section>`).join('')||empty('No auctions scheduled','Upcoming industrial auctions will appear here.')}</div><div class="notice">Bids are binding under the auction’s agreed terms. Request approval before bidding. Current bids update when you refresh. If enabled, a bid in the final two minutes extends closing by two minutes.</div>`;}
function rentalsPage(rows,bookings,portal){const manager=portal&&['admin','operations'].includes(state.user.role);return pageTitle('REBUILD LEASE','Rentals & bookings','Request equipment for your project. Availability is confirmed by operations.',manager?button(icon('plus')+' Add rental equipment','rental-form'):'')+`${portal&&!state.features.rentals?'<div class="notice">Rentals are hidden publicly. Super Admin can launch them from Service launch controls.</div>':''}<div class="exchange-grid">${rows.map(r=>`<section class="panel exchange-card">${media(r.icon)}<h2>${esc(r.title)}</h2><p class="muted">${esc(r.location)}</p><div class="exchange-price"><small>Daily rate</small><strong>${money(r.daily_rate)} <small>/ day</small></strong><span>Deposit: ${money(r.deposit)} · Managed separately</span></div><p>${esc(r.terms)}</p>${!manager?button('Request dates','booking-form','primary small',`data-id="${r.id}"`):badge('Available')}</section>`).join('')||empty('No rental equipment yet','Available equipment and rental terms will appear here.')}</div>${portal?`<h2 class="subsection-title">Booking requests</h2><section class="panel table-wrap"><table><thead><tr><th>Equipment / customer</th><th>Dates</th><th>Rental total</th><th>Status</th><th></th></tr></thead><tbody>${bookings.map(b=>`<tr><td><strong>${esc(b.title)}</strong><small>${esc(b.customer_name)}</small></td><td>${esc(b.start_date)} → ${esc(b.end_date)}</td><td>${money(b.total)}</td><td>${badge(b.status)}</td><td>${manager?({'Requested':button('Confirm','booking-status','primary small',`data-id="${b.id}" data-status="Confirmed"`),'Confirmed':button('Record pickup','booking-status','secondary small',`data-id="${b.id}" data-status="Active"`),'Active':button('Record return','booking-status','secondary small',`data-id="${b.id}" data-status="Returned"`)}[b.status]||''):''}</td></tr>`).join('')}</tbody></table>${!bookings.length?empty('No booking requests','Your rental requests will appear here.'):''}</section>`:''}`;}
async function exchangeAction(action,el){const aid=el.dataset.id;if(action==='feature-toggle'){const key=el.dataset.key;await api('/features',{[key]:!state.features[key]});toast('Service visibility updated');await render();return true;}
 if(action==='auction-form'||action==='rental-form'){const assets=await api('/assets?scope=admin');const available=assets.filter(a=>['Approved','Published'].includes(a.review_status));if(!available.length)throw Error('Approve an asset before adding an auction or rental.');const auction=action==='auction-form';modal(auction?'Schedule an auction':'Add rental equipment',`<form id="${action}"><div class="form-grid">${select('Equipment','asset_id',available.map(a=>({id:a.id,name:a.title})))}${auction?field('Auction title','title','','text','required minlength="3"')+field('Starts (your local time)','starts_at','','datetime-local','required')+field('Ends (your local time)','ends_at','','datetime-local','required')+field('Opening bid (₹)','start_price','','number','required min="1" step="0.01"')+field('Reserve price (₹)','reserve','','number','required min="0" step="0.01"')+field('Bid increment (₹)','increment','','number','required min="1" step="0.01"'):field('Daily rate (₹)','daily_rate','','number','required min="1" step="0.01"')+field('Deposit (₹)','deposit','','number','required min="0" step="0.01"')+area('Rental terms, responsibilities & insurance','terms','','required minlength="10"')}</div><div class="notice">Agreements and payment arrangements must be coordinated separately. No deposits or payments are collected here.</div>${formEnd(auction?'Schedule auction':'Add rental')}`,true);return true;}
 if(action==='auction-join'){if(!signedIn())return true;await api('/auctions/'+aid+'/join',{});toast('Participation requested. Await manager approval.');await render();return true;}
 if(action==='auction-bid-form'){if(!signedIn())return true;const a=state.data.find(x=>x.id===aid);modal('Place an auction bid',`<form id="bid-form" data-id="${aid}"><p>${esc(a.title)}</p>${field('Bid amount (₹)','amount',((a.current_bid?a.current_bid+a.increment:a.start_price)/100),'number','required min="1" step="0.01"')}<div class="notice">Confirm the amount before submitting. Every bid is recorded in the audit trail.</div>${formEnd('Submit bid')}`);return true;}
 if(action==='auction-participants'){const rows=await api('/auctions/'+aid+'/participants');modal('Review auction participants',`<div class="bidder-list">${rows.map(p=>`<div class="bidder"><strong>${esc(p.name)}</strong><p>${esc(p.email)}</p>${badge(p.status)}<div class="row-actions">${button('Approve','bidder-status','primary small',`data-auction="${aid}" data-id="${p.user_id}" data-status="Approved"`)}${button('Reject','bidder-status','secondary small',`data-auction="${aid}" data-id="${p.user_id}" data-status="Rejected"`)}</div></div>`).join('')||empty('No bidder requests','Participation requests will appear here.')}</div>`);return true;}
 if(action==='bidder-status'){await api('/auctions/'+el.dataset.auction+'/participants',{user_id:aid,status:el.dataset.status});toast('Bidder '+el.dataset.status.toLowerCase());closeModal();await render();return true;}
 if(action==='auction-close'){await api('/auctions/'+aid+'/close',{});toast('Auction result recorded');await render();return true;}
 if(action==='booking-form'){if(!signedIn())return true;modal('Request rental dates',`<form id="booking-form" data-id="${aid}"><div class="form-grid">${field('Start date','start_date','','date','required min="'+new Date().toISOString().slice(0,10)+'"')}${field('End date (inclusive)','end_date','','date','required min="'+new Date().toISOString().slice(0,10)+'"')}</div><div class="notice">Operations must confirm availability. The total uses inclusive calendar days; deposits are arranged separately.</div>${formEnd('Request booking')}`);return true;}
 if(action==='booking-status'){await api('/bookings',{id:aid,status:el.dataset.status});toast('Booking status updated');await render();return true;}return false;}
async function exchangeSubmit(form,v){if(form.id==='auction-form'){await api('/auctions',{...v,starts_at:new Date(v.starts_at).toISOString(),ends_at:new Date(v.ends_at).toISOString(),start_price:Math.round(Number(v.start_price)*100),reserve:Math.round(Number(v.reserve)*100),increment:Math.round(Number(v.increment)*100)});toast('Auction scheduled');return true;}if(form.id==='rental-form'){await api('/rentals',{...v,daily_rate:Math.round(Number(v.daily_rate)*100),deposit:Math.round(Number(v.deposit)*100)});toast('Rental added');return true;}if(form.id==='bid-form'){await api('/auctions/'+form.dataset.id+'/bid',{amount:Math.round(Number(v.amount)*100)});toast('Bid recorded');return true;}if(form.id==='booking-form'){await api('/rentals/'+form.dataset.id+'/book',v);toast('Booking requested');return true;}return false;}
function assetMedia(a){return a.photo_id?`<img class="uploaded-photo" src="/api/photos/${a.photo_id}" alt="${esc(a.title)}" loading="lazy">`:state.demo?media(a.icon):`<div class="photo-placeholder">${icon(a.icon)}<small>Photos coming soon</small></div>`;}
function dataRoomPage(rows){return pageTitle('CONFIDENTIAL. CONTROLLED. AUDITED.','Shared data rooms','Share business documents only after an externally signed NDA, with an explicit access expiry.')+`<div class="notice">Upload documents in the private vault first, then attach them to a mandate. Buyers must register before access is granted. Download events are audited; access expires automatically.</div><div class="enquiry-list">${rows.map(r=>`<section class="panel"><h2>${esc(r.title)}</h2><div class="room-documents">${r.documents.map(d=>`<a href="/api/documents/${d.id}" class="room-document">${icon('file')}<span>${esc(d.name)}</span>${icon('arrow')}</a>`).join('')||'<p class="muted">No documents attached yet.</p>'}</div>${r.can_manage?`<div class="row-actions">${button('Attach company document','room-attach-form','secondary small',`data-id="${r.id}"`)}${button('Grant buyer access','room-grant-form','primary small',`data-id="${r.id}"`)}</div><h3 class="room-heading">Access history</h3>${r.grants.map(g=>`<div class="room-grant"><strong>${esc(g.user_name)}</strong><small>${esc(g.email)} · Expires ${date(g.expires_at)}</small><p>NDA: ${esc(g.nda_reference)}</p>${g.revoked||Date.parse(g.expires_at)<Date.now()?badge('Expired / revoked'):button('Revoke access','room-revoke','secondary small',`data-id="${r.id}" data-grant="${g.id}"`)}</div>`).join('')||'<p class="muted">No external access granted.</p>'}`:'<p class="muted">Your access is time-limited and downloads are audited.</p>'}</section>`).join('')||empty('No shared data rooms','Submit a business mandate or ask the business owner for access.')}</div>`;}
async function privateAction(action,el){const aid=el.dataset.id;
 if(action==='asset-photo-form'){modal('Add an equipment photo',`<form id="asset-photo-form" data-id="${aid}">${field('Equipment photo','file','','file','required accept="image/png,image/jpeg"')}<p class="muted">JPEG or PNG · Up to 8 MB · Maximum eight photos per asset. The first photo is used on the marketplace.</p>${formEnd('Upload photo')}`);return true;}
 if(action==='room-attach-form'){const docs=await api('/documents');if(!docs.length)throw Error('Upload a document to your private vault first.');modal('Attach a private document',`<form id="room-attach-form" data-id="${aid}">${select('Company document','document_id',docs)}${formEnd('Attach to data room')}`);return true;}
 if(action==='room-grant-form'){modal('Grant confidential access',`<form id="room-grant-form" data-id="${aid}">${field('Registered buyer email','email','','email','required')}${field('Signed NDA reference','nda_reference','','text','required minlength="3" placeholder="External signed agreement ID"')}${field('Access expires (within 30 days)','expires_at','','datetime-local','required')}<div class="notice">Confirm that the NDA has been signed outside this platform before granting access. The buyer will be able to download every attached document until expiry or revocation.</div>${formEnd('Grant access')}`);return true;}
 if(action==='room-revoke'){await api('/data-room',{action:'revoke',mandate_id:aid,grant_id:el.dataset.grant});toast('Access revoked immediately');await render();return true;}return false;}
async function privateSubmit(form,v,data){if(form.id==='asset-photo-form'){const file=data.get('file');if(file.size>8*1024*1024)throw Error('Image exceeds 8 MB');const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await api('/assets/'+form.dataset.id+'/photos',{content});toast('Equipment photo uploaded');return true;}if(form.id==='room-attach-form'){await api('/data-room',{action:'attach',mandate_id:form.dataset.id,document_id:v.document_id});toast('Document attached');return true;}if(form.id==='room-grant-form'){await api('/data-room',{...v,action:'grant',mandate_id:form.dataset.id,expires_at:new Date(v.expires_at).toISOString()});toast('Buyer access granted');return true;}return false;}
function categoryChildren(rows,parent,depth=0){return rows.filter(c=>c.parent_id===parent).map(c=>`<div style="padding-left:${depth*10}px"><span>${depth?'↳ ':''}${esc(c.name)}</span><div>${!c.effective_active&&c.active?'<small>Parent off</small>':''}<button class="switch small ${c.active&&!c.archived?'on':''}" role="switch" aria-checked="${!!c.active&&!c.archived}" aria-label="Enable ${esc(c.name)}" data-action="category-toggle" data-id="${c.id}"><span></span></button>${button(icon('edit'),'category-form','icon-btn',`data-id="${c.id}" aria-label="Edit ${esc(c.name)}"`)}</div></div>${categoryChildren(rows,c.id,depth+1)}`).join('');}
function browseExtraFilters(cats,params){const cat=cats.find(c=>c.id===params.get('category'));return `<details class="extra-filters"><summary>${icon('settings')} More filters · Price, condition & specifications</summary><form id="extra-filters"><div class="extra-filter-grid">${field('Minimum price (₹)','min',params.get('min')?Number(params.get('min'))/100:'','number','min="0" step="0.01"')}${field('Maximum price (₹)','max',params.get('max')?Number(params.get('max'))/100:'','number','min="0" step="0.01"')}${field('Brand','brand',params.get('brand')||'')}${select('Condition','condition',[{id:'',name:'Any condition'},'Used','Refurbished','Unused surplus','For parts'],params.get('condition')||'')}${(cat?.attributes||[]).filter(a=>a.filterable&&a.type!=='file').map(a=>a.type==='dropdown'?select(a.label,'spec.'+a.key,[{id:'',name:'Any'},...a.options],params.get('spec.'+a.key)||''):field(a.label+(a.unit?' ('+a.unit+')':''),'spec.'+a.key,params.get('spec.'+a.key)||'')).join('')}</div><button class="btn primary small">Apply filters</button></form></details>`;}
function certificatesPage(rows){return pageTitle('DOCUMENTED SCOPE. VERIFIABLE STATUS.','Technical certificates','Public certificate pages contain only explicitly approved summaries and limitations.',['admin','operations'].includes(state.user.role)?button(icon('plus')+' Issue certificate','certificate-form'):'')+`<div class="panel table-wrap"><table><thead><tr><th>Certificate / report</th><th>Issued</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.id)}</strong><small>${esc(c.title)}</small></td><td>${date(c.issued_at)}</td><td>${badge(c.status)}</td><td><div class="row-actions"><a href="#/certificate/${c.id}" class="btn secondary small">Public verification ${icon('arrow')}</a>${c.status==='Valid'&&state.user.role==='admin'?button('Revoke','certificate-revoke-form','ghost small',`data-id="${c.id}"`):''}</div></td></tr>`).join('')}</tbody></table>${!rows.length?empty('No certificates issued','Approve an inspection report before issuing its technical certificate.'):''}</div>`;}
function certificatePublic(c){return `<main class="certificate-page"><section class="panel"><span class="icon-tile">${icon('shield')}</span><span class="eyebrow">REBUILD CERTIFIED · PUBLIC VERIFICATION</span><h1>Technical inspection record</h1>${badge(c.status)}<h2>${esc(c.title)}</h2><code>${esc(c.id)}</code><p class="muted">Issued ${date(c.issued_at)}</p><h3>Approved public summary</h3><p class="preserve">${esc(c.public_summary)}</p><h3>Scope & limitations</h3><p class="preserve">${esc(c.scope)}</p>${c.status==='Revoked'?`<div class="notice"><strong>Certificate revoked</strong><p>${esc(c.revocation_reason)}</p></div>`:''}<div class="notice">This certificate records a technical inspection at a point in time. It is not a warranty, valuation, ownership guarantee or legal-clearance certificate.</div>${button('Print / save as PDF','certificate-print','secondary')}</section></main>`;}
async function certificateAction(action,el){if(action==='certificate-print'){window.print();return true;}if(action==='certificate-form'){const rows=(await api('/records?kind=inspection')).filter(r=>r.status==='Approved');if(!rows.length)throw Error('Approve a technical inspection report before issuing a certificate.');modal('Issue a technical certificate',`<form id="certificate-form">${select('Approved inspection report','report_id',rows.map(r=>({id:r.id,name:r.title})))}${area('Public summary (safe to publish)','public_summary','','required minlength="10"')}${area('Scope, limitations and exclusions','scope','','required minlength="10"')}<div class="notice">These two text fields will be publicly visible. Do not include seller identities, private documents or confidential technical information.</div>${formEnd('Issue certificate')}`);return true;}if(action==='certificate-revoke-form'){modal('Revoke technical certificate',`<form id="certificate-revoke-form" data-id="${el.dataset.id}">${area('Public revocation reason','reason','','required minlength="10"')}${formEnd('Revoke certificate')}`);return true;}return false;}
async function certificateSubmit(form,v){if(form.id==='certificate-form'){await api('/certificates',v);toast('Certificate issued');return true;}if(form.id==='certificate-revoke-form'){await api('/certificates/'+form.dataset.id+'/revoke',v);toast('Certificate revoked');return true;}return false;}
